import 'package:json_annotation/json_annotation.dart';part 'coach_make_list_response.g.dart';@JsonSerializable()class CoachMakeListResponse {  final bool success;  final String message;  final List<CoachMakeItem>? data;  CoachMakeListResponse({    required this.success,    required this.message,    this.data,  });  factory CoachMakeListResponse.fromJson(Map<String, dynamic> json) =>      _$CoachMakeListResponseFromJson(json);  Map<String, dynamic> toJson() => _$CoachMakeListResponseToJson(this);}@JsonSerializable()class CoachMakeItem {  @JsonKey(name: 'id')  final int? id;  final String? name;  CoachMakeItem({    this.id,    this.name,  });  factory CoachMakeItem.fromJson(Map<String, dynamic> json) =>      _$CoachMakeItemFromJson(json);  Map<String, dynamic> toJson() => _$CoachMakeItemToJson(this);}